    54          zip_source_close(src);
    55      }
    56      if (ZIP_SOURCE_IS_OPEN_WRITING(src)) {
    57          zip_source_rollback_write(src);
    58      }
    59
    60      if (src->source_archive && !src->source_closed) {
    61          _zip_deregister_source(src->source_archive, src);
    62      }
    63
    64      (void)_zip_source_call(src, NULL, 0, ZIP_SOURCE_FREE);
    65
    66      if (src->src) {
    67          zip_source_free(src->src);
    68      }
